@Service
public class DepositAccountWaveDService {
    private static final Set<String> RECON_TYPES=Set.of("BALANCE","TRANSACTION","PROFIT","FEE","TAX","SUSPENSE");
    private static final Set<String> EXC_TYPES=Set.of("INCOMPLETE_TRANSACTION","DUPLICATE_TRANSACTION","RECONCILIATION","PROFIT","FEE","TAX");
    private static final Set<String> EXC_REASONS=Set.of("DATA_MISMATCH","DUPLICATE_POSTING","MISSING_REFERENCE","BALANCE_DIFFERENCE","RULE_VIOLATION","SYSTEM_ERROR");
    private static final Set<String> CORR_TYPES=Set.of("REVERSAL","CORRECTION","BACKDATED_CORRECTION","DUPLICATE_CANCEL");
    private static final Set<String> CORR_REASONS=Set.of("CUSTOMER_COMPLAINT","OPERATOR_ERROR","DUPLICATE_POSTING","SYSTEM_ERROR","ACCOUNTING_ADJUSTMENT","REGULATORY_ORDER");
    private final DepositAccountWaveDRepository repository; private final DepositTransactionService transactions; private final DepositBalanceService balances; private final SecureRandom secureRandom=new SecureRandom();
    public DepositAccountWaveDService(DepositAccountWaveDRepository repository,DepositTransactionService transactions,DepositBalanceService balances){this.repository=repository;this.transactions=transactions;this.balances=balances;}

    @Transactional(readOnly=true) public WaveDView get(long accountId){requireAccount(accountId);return view(accountId);}

    @Transactional public WaveDView startReconciliation(long accountId,ReconciliationRunRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Reconciliation Run الزامی است.");String type=upper(required(r.reconciliationTypeCode(),"RECONCILIATION_TYPE_CODE"));if(!RECON_TYPES.contains(type))throw new IllegalArgumentException("RECONCILIATION_TYPE_CODE نامعتبر است.");LocalDate bd=r.businessDate()==null?LocalDate.now():r.businessDate();String src=upper(required(r.sourceSystemCode(),"SOURCE_SYSTEM_CODE")),target=upper(required(r.targetLedgerCode(),"TARGET_LEDGER_CODE"));String h=hash("RECON_RUN|"+accountId+"|"+bd+"|"+type+"|"+src+"|"+target);if(replayOrClaim(idem,accountId,"RECONCILIATION_RUN",h,actor,corr))return view(accountId);Long existing=repository.findReconRun(bd,type,src,target);long id=existing==null?repository.next("SEQ_DEPOSIT_RECONCILIATION_RUN"):existing;if(existing==null)repository.insertReconRun(id,bd,type,src,target,actor);repository.completeIdempotency(idem,"RECONRUN:"+id);return view(accountId);}
    @Transactional public WaveDView addReconciliationItem(long accountId,long runId,ReconciliationItemRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Reconciliation Item الزامی است.");BigDecimal sa=r.sourceAmount()==null?BigDecimal.ZERO:r.sourceAmount(),ta=r.targetAmount()==null?BigDecimal.ZERO:r.targetAmount();BigDecimal diff=sa.subtract(ta);String match=diff.signum()==0?"MATCHED":"MISMATCHED",dtype=diff.signum()==0?null:upper(Optional.ofNullable(r.discrepancyTypeCode()).orElse("BALANCE_DIFFERENCE")),sev=upper(Optional.ofNullable(r.severityCode()).orElse("MEDIUM"));String h=hash("RECON_ITEM|"+accountId+"|"+runId+"|"+r.sourceReference()+"|"+r.targetReference()+"|"+sa+"|"+ta);if(replayOrClaim(idem,accountId,"RECONCILIATION_ITEM",h,actor,corr))return view(accountId);long item=repository.next("SEQ_DEPOSIT_RECONCILIATION_ITEM");repository.insertReconItem(item,runId,accountId,trim(r.sourceReference()),trim(r.targetReference()),sa,ta,match,dtype,actor);if(diff.signum()!=0){long d=repository.next("SEQ_DEPOSIT_DISCREPANCY");repository.insertDiscrepancy(d,item,dtype,sa,ta,sev,actor);}repository.completeReconRun(runId,actor);repository.completeIdempotency(idem,"RECONITEM:"+item);return view(accountId);}
    @Transactional public WaveDView openSuspenseItem(long accountId,SuspenseOpenItemRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Suspense Open Item الزامی است.");ReconItemSuspenseSource item=repository.reconciliationItemForSuspense(r.reconciliationItemId(),accountId);if(item==null||!"MISMATCHED".equals(item.matchStatusCode()))throw new IllegalArgumentException("Reconciliation Item مغایرت‌دار برای ثبت قلم باز یافت نشد.");BigDecimal amount=r.amount()==null?item.differenceAmount().abs():r.amount();if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("AMOUNT قلم باز باید مثبت باشد.");String code=upper(Optional.ofNullable(trim(r.suspenseAccountCode())).orElse("DPS2_RECON_SUSPENSE"));String source=Optional.ofNullable(trim(r.sourceReference())).orElse("RECON-ITEM-"+item.reconciliationItemId());String h=hash("SUSPENSE_OPEN|"+accountId+"|"+item.reconciliationItemId()+"|"+code+"|"+source+"|"+amount+"|"+r.slaDueAt());if(replayOrClaim(idem,accountId,"SUSPENSE_OPEN",h,actor,corr))return view(accountId);Long existing=repository.existingSuspenseId(code,source);if(existing!=null){repository.completeIdempotency(idem,"SUSPENSE:"+existing);return view(accountId);}long id=repository.next("SEQ_DEPOSIT_SUSPENSE_OPEN_ITEM");repository.insertSuspense(id,accountId,code,source,amount,repository.accountCurrency(accountId),r.slaDueAt(),actor);repository.completeIdempotency(idem,"SUSPENSE:"+id);return view(accountId);}

    @Transactional public WaveDView openException(long accountId,ExceptionRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Exception Case الزامی است.");String type=upper(required(r.exceptionTypeCode(),"EXCEPTION_TYPE_CODE")),reason=upper(required(r.reasonCode(),"REASON_CODE")),severity=upper(required(r.severityCode(),"SEVERITY_CODE")),queue=upper(required(r.queueCode(),"QUEUE_CODE"));if(!EXC_TYPES.contains(type)||!EXC_REASONS.contains(reason))throw new IllegalArgumentException("Exception type/reason نامعتبر است.");String h=hash("EXCEPTION|"+accountId+"|"+r.transactionId()+"|"+type+"|"+reason+"|"+queue);if(replayOrClaim(idem,accountId,"EXCEPTION_OPEN",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_EXCEPTION_CASE");repository.insertException(id,accountId,r.transactionId(),type,reason,severity,queue,r.slaDueAt(),actor);repository.insertAssignment(repository.next("SEQ_DEPOSIT_EXCEPTION_ASSIGNMENT"),id,queue,null,r.slaDueAt(),actor);repository.completeIdempotency(idem,"EXCEPTION:"+id);return view(accountId);}
    @Transactional public WaveDView referDiscrepancy(long accountId,long discrepancyId,ExceptionRequest r,String actor,String corr,String idem){WaveDView v=openException(accountId,r,actor,corr,idem);long exceptionId=v.exceptions().cases().isEmpty()?0:v.exceptions().cases().get(0).exceptionCaseId();if(exceptionId>0)repository.linkDiscrepancy(discrepancyId,exceptionId,actor);return view(accountId);}
    @Transactional public WaveDView assignException(long accountId,long exceptionId,AssignmentRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Assignment الزامی است.");String h=hash("EXC_ASSIGN|"+accountId+"|"+exceptionId+"|"+r.queueCode()+"|"+r.assigneeReference());if(replayOrClaim(idem,accountId,"EXCEPTION_ASSIGN",h,actor,corr))return view(accountId);repository.insertAssignment(repository.next("SEQ_DEPOSIT_EXCEPTION_ASSIGNMENT"),exceptionId,upper(required(r.queueCode(),"QUEUE_CODE")),trim(r.assigneeReference()),r.slaDueAt(),actor);repository.completeIdempotency(idem,"EXCASSIGN:"+exceptionId);return view(accountId);}
    @Transactional public WaveDView requestCorrection(long accountId,CorrectionRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Correction Request الزامی است.");String type=upper(required(r.correctionTypeCode(),"CORRECTION_TYPE_CODE")),reason=upper(required(r.reasonCode(),"REASON_CODE")),approver=required(r.approverUserId(),"APPROVER_USER_ID");if(!CORR_TYPES.contains(type)||!CORR_REASONS.contains(reason))throw new IllegalArgumentException("Correction type/reason نامعتبر است.");if(actor.equalsIgnoreCase(approver))throw new IllegalArgumentException("Maker و Approver باید متفاوت باشند.");boolean reversal="REVERSAL".equals(type)||"DUPLICATE_CANCEL".equals(type);if(reversal&&(r.originalTransactionId()==null||!repository.postedTransaction(accountId,r.originalTransactionId())))throw new IllegalArgumentException(type+" فقط برای تراکنش POSTED همین حساب مجاز است.");LocalDate ed=r.requestedEffectiveDate()==null?LocalDate.now():r.requestedEffectiveDate();String h=hash("CORR_REQ|"+accountId+"|"+r.originalTransactionId()+"|"+r.exceptionCaseId()+"|"+type+"|"+reason+"|"+ed+"|"+approver);if(replayOrClaim(idem,accountId,"CORRECTION_REQUEST",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_CORRECTION_REQUEST");repository.insertCorrectionRequest(id,accountId,r.originalTransactionId(),r.exceptionCaseId(),type,reason,ed,actor,actor);repository.insertCorrectionAuthorization(repository.next("SEQ_DEPOSIT_CORRECTION_AUTHORIZATION"),id,approver,actor);repository.completeIdempotency(idem,"CORRREQ:"+id);return view(accountId);}
    @Transactional public WaveDView approveCorrection(long accountId,long correctionId,String actor,String corr,String idem){requireAccount(accountId);String h=hash("CORR_APPROVE|"+accountId+"|"+correctionId+"|"+actor);if(replayOrClaim(idem,accountId,"CORRECTION_APPROVE",h,actor,corr))return view(accountId);CorrectionLock c=repository.correction(accountId,correctionId);if(c==null||!"PENDING_APPROVAL".equals(c.status())||!"PENDING".equals(c.decision())||!actor.equals(c.approver()))throw new IllegalArgumentException("Correction/Approver معتبر نیست.");if(repository.approveCorrection(c,actor)!=1)throw new IllegalStateException("Correction همزمان تغییر کرده است.");repository.completeIdempotency(idem,"CORRAPPROVED:"+correctionId);return view(accountId);}
    @Transactional public WaveDView executeCorrection(long accountId,long correctionId,String actor,String corr,String idem){requireAccount(accountId);String h=hash("CORR_EXEC|"+accountId+"|"+correctionId);if(replayOrClaim(idem,accountId,"CORRECTION_EXECUTE",h,actor,corr))return view(accountId);CorrectionLock c=repository.correction(accountId,correctionId);if(c==null||!"APPROVED".equals(c.status()))throw new IllegalArgumentException("Correction تأییدشده یافت نشد.");Long original=c.originalTransactionId(),corrective=null;BigDecimal amount=null;String posting=null;boolean reversal="REVERSAL".equals(c.type())||"DUPLICATE_CANCEL".equals(c.type());if(reversal){var result=transactions.reverse(accountId,Objects.requireNonNull(original),new ReversalRequest("DUPLICATE_CANCEL".equals(c.type())?"DUPLICATE_POSTING":"CORRECTION_REQUEST"),actor,corr,idem+"-TXREV");corrective=result.transaction().transaction().transactionId();amount=repository.transactionAmount(original);posting="DPS2-CORR-"+correctionId;}else if(original!=null){amount=repository.transactionAmount(original);}long entry=repository.next("SEQ_DEPOSIT_CORRECTION_ENTRY");repository.insertCorrectionEntry(entry,correctionId,original,corrective,c.type(),c.effectiveDate(),amount,posting,"CORRECTION_REQUEST:"+correctionId,actor);repository.completeIdempotency(idem,"CORRENTRY:"+entry);return view(accountId);}
    @Transactional public WaveDView rootCause(long accountId,long exceptionId,RootCauseRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Root Cause Analysis الزامی است.");String h=hash("RCA|"+accountId+"|"+exceptionId+"|"+r.rootCauseCode()+"|"+r.description());if(replayOrClaim(idem,accountId,"ROOT_CAUSE",h,actor,corr))return view(accountId);repository.upsertRootCause(repository.next("SEQ_DEPOSIT_ROOT_CAUSE_ANALYSIS"),exceptionId,upper(required(r.rootCauseCode(),"ROOT_CAUSE_CODE")),required(r.description(),"ROOT_CAUSE_DESCRIPTION"),trim(r.correctiveAction()),trim(r.preventiveAction()),trim(r.ownerReference()),r.targetDate(),actor);repository.completeIdempotency(idem,"RCA:"+exceptionId);return view(accountId);}

    @Transactional public CorrespondentAccountCreation createCorrespondentAccount(CorrespondentRequest r,String actor,String corr,String idem){if(r==null)throw new IllegalArgumentException("Correspondent account الزامی است.");String type=upper(required(r.accountTypeCode(),"ACCOUNT_TYPE_CODE")),freq=upper(required(r.reconciliationFrequencyCode(),"RECONCILIATION_FREQUENCY_CODE"));if(!Set.of("NOSTRO","VOSTRO").contains(type)||!Set.of("INTRADAY","DAILY","WEEKLY").contains(freq))throw new IllegalArgumentException("Correspondent type/frequency نامعتبر است.");BigDecimal tol=r.toleranceAmount()==null?BigDecimal.ZERO:r.toleranceAmount();if(tol.signum()<0)throw new IllegalArgumentException("TOLERANCE_AMOUNT منفی مجاز نیست.");String cur=upper(required(r.settlementCurrencyCode(),"SETTLEMENT_CURRENCY_CODE")),external=required(r.externalAccountReference(),"EXTERNAL_ACCOUNT_REFERENCE"),statement=upper(required(r.statementSourceCode(),"STATEMENT_SOURCE_CODE"));Long pv=repository.correspondentProductVersion(type,cur);if(pv==null)throw new CorrespondentProductProfileNotFoundException(type,cur);String h=hash("CORRESPONDENT_ACCOUNT_CREATE|"+type+"|"+r.correspondentBankPartyId()+"|"+external+"|"+cur+"|"+freq);var prior=repository.idempotency(idem);if(prior.isPresent()){var x=prior.get();if(!"CORRESPONDENT_ACCOUNT_CREATE".equals(x.operation())||!h.equals(x.payloadHash())||!"COMPLETED".equals(x.status())||x.resultReference()==null||!x.resultReference().startsWith("CORRESPONDENT_ACCOUNT:"))throw new IllegalArgumentException("Idempotency key با درخواست دیگری استفاده شده است.");long existing=Long.parseLong(x.resultReference().substring("CORRESPONDENT_ACCOUNT:".length()));return new CorrespondentAccountCreation(existing,repository.correspondents(existing).isEmpty()?"":repository.accountNo(existing),repository.currentProductVersion(existing),view(existing));}long id=repository.next("SEQ_DEPOSIT_ACCOUNT");String accountNo=("NOSTRO".equals(type)?"NS-":"VS-")+(10000L+id);repository.claimIdempotency(repository.next("SEQ_DEPOSIT_OPERATION_IDEMPOTENCY"),idem,null,"CORRESPONDENT_ACCOUNT_CREATE",h,actor,corr);String bic=upper(trim(r.correspondentBic()));String name="حساب "+type+(bic==null?"":" - "+bic);repository.insertCorrespondentAccountMaster(id,accountNo,pv,cur,name,actor);balances.initializeAccount(id,cur,actor);repository.upsertCorrespondent(repository.next("SEQ_CORRESPONDENT_ACCOUNT_EXTENSION"),repository.next("SEQ_CORRESPONDENT_RECONCILIATION_PROFILE"),id,type,r.correspondentBankPartyId(),bic,external,cur,statement,freq,r.autoMatchAllowed()==null||r.autoMatchAllowed(),tol,actor);repository.completeIdempotency(idem,"CORRESPONDENT_ACCOUNT:"+id);return new CorrespondentAccountCreation(id,accountNo,pv,view(id));}

    @Transactional public WaveDView configureCorrespondent(long accountId,CorrespondentRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Correspondent configuration الزامی است.");String type=upper(required(r.accountTypeCode(),"ACCOUNT_TYPE_CODE")),freq=upper(required(r.reconciliationFrequencyCode(),"RECONCILIATION_FREQUENCY_CODE"));if(!Set.of("NOSTRO","VOSTRO").contains(type)||!Set.of("INTRADAY","DAILY","WEEKLY").contains(freq))throw new IllegalArgumentException("Correspondent type/frequency نامعتبر است.");BigDecimal tol=r.toleranceAmount()==null?BigDecimal.ZERO:r.toleranceAmount();if(tol.signum()<0)throw new IllegalArgumentException("TOLERANCE_AMOUNT منفی مجاز نیست.");String cur=upper(required(r.settlementCurrencyCode(),"SETTLEMENT_CURRENCY_CODE"));String h=hash("CORRESPONDENT|"+accountId+"|"+type+"|"+r.correspondentBankPartyId()+"|"+r.externalAccountReference()+"|"+cur+"|"+freq);if(replayOrClaim(idem,accountId,"CORRESPONDENT_CONFIG",h,actor,corr))return view(accountId);repository.upsertCorrespondent(repository.next("SEQ_CORRESPONDENT_ACCOUNT_EXTENSION"),repository.next("SEQ_CORRESPONDENT_RECONCILIATION_PROFILE"),accountId,type,r.correspondentBankPartyId(),upper(trim(r.correspondentBic())),required(r.externalAccountReference(),"EXTERNAL_ACCOUNT_REFERENCE"),cur,upper(required(r.statementSourceCode(),"STATEMENT_SOURCE_CODE")),freq,r.autoMatchAllowed()==null||r.autoMatchAllowed(),tol,actor);repository.completeIdempotency(idem,"CORRESPONDENT:"+accountId);return view(accountId);}

    @Transactional public WaveDView completeCorrespondentReconciliation(long accountId,CorrespondentReconciliationRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Correspondent reconciliation الزامی است.");if(!repository.completedReconRunForAccount(r.reconciliationRunId(),accountId))throw new IllegalArgumentException("Reconciliation Run تکمیل‌شده برای این حساب یافت نشد.");String h=hash("CORRESPONDENT_RECON|"+accountId+"|"+r.reconciliationRunId());if(replayOrClaim(idem,accountId,"CORRESPONDENT_RECONCILIATION",h,actor,corr))return view(accountId);if(repository.markCorrespondentReconciled(accountId,actor)==0)throw new IllegalArgumentException("Correspondent profile برای حساب یافت نشد.");repository.completeIdempotency(idem,"CORRESPONDENT_RECON:"+r.reconciliationRunId());return view(accountId);}

    @Transactional public WaveDView createRewardProgram(long accountId,RewardProgramRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Reward Program الزامی است.");String type=upper(required(r.programTypeCode(),"PROGRAM_TYPE_CODE"));if(!Set.of("LOTTERY","REWARD","BONUS").contains(type))throw new IllegalArgumentException("PROGRAM_TYPE_CODE نامعتبر است.");LocalDate from=r.effectiveFrom()==null?LocalDate.now():r.effectiveFrom();if(r.effectiveTo()!=null&&r.effectiveTo().isBefore(from))throw new IllegalArgumentException("EFFECTIVE_TO قبل از EFFECTIVE_FROM مجاز نیست.");BigDecimal min=Objects.requireNonNullElse(r.minAverageBalance(),BigDecimal.ZERO),unit=r.entryUnitAmount();if(min.signum()<0||unit==null||unit.signum()<=0||r.minActiveDays()!=null&&r.minActiveDays()<0)throw new IllegalArgumentException("MIN_AVERAGE_BALANCE/MIN_ACTIVE_DAYS/ENTRY_UNIT_AMOUNT نامعتبر است.");String code=trim(r.programCode());if(code==null)code="RWD-"+System.currentTimeMillis();String h=hash("REWARD_PROGRAM|"+accountId+"|"+code+"|"+type+"|"+from+"|"+r.effectiveTo()+"|"+min+"|"+r.minActiveDays()+"|"+(r.excludeDormant()==null||r.excludeDormant())+"|"+unit);if(replayOrClaim(idem,accountId,"REWARD_PROGRAM_CREATE",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_REWARD_PROGRAM");repository.insertRewardProgram(id,code,required(r.programName(),"PROGRAM_NAME"),type,repository.currentProductVersion(accountId),from,r.effectiveTo(),actor);repository.insertRewardEligibilityRule(repository.next("SEQ_DEPOSIT_REWARD_ELIGIBILITY_RULE"),id,min,r.minActiveDays(),r.excludeDormant()==null||r.excludeDormant(),unit,actor);repository.completeIdempotency(idem,"REWARD_PROGRAM:"+id);return view(accountId);}

    @Transactional public WaveDView enrollReward(long accountId,RewardEnrollmentRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Reward Enrollment الزامی است.");if(!repository.programApplicable(r.programId(),accountId))throw new IllegalArgumentException("Reward Program فعال/قابل اعمال برای این حساب نیست.");boolean eligible=repository.programEligible(r.programId(),accountId);String h=hash("REWARD_ENROLL|"+accountId+"|"+r.programId()+"|"+r.consentReference()+"|"+eligible);if(replayOrClaim(idem,accountId,"REWARD_ENROLL",h,actor,corr))return view(accountId);repository.upsertEnrollment(repository.next("SEQ_DEPOSIT_REWARD_ENROLLMENT"),r.programId(),accountId,trim(r.consentReference()),eligible,actor);repository.completeIdempotency(idem,"REWARDENROLL:"+r.programId()+":"+(eligible?"ELIGIBLE":"INELIGIBLE"));return view(accountId);}

    @Transactional public WaveDView createLotteryDraw(long accountId,LotteryDrawRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Lottery Draw الزامی است.");if(!repository.activeProgramForAccount(r.programId(),accountId))throw new IllegalArgumentException("Reward Program فعال/مجاز برای این حساب نیست.");LocalDate drawDate=r.drawDate()==null?LocalDate.now():r.drawDate(),cutoff=r.eligibilityCutoffDate()==null?drawDate:r.eligibilityCutoffDate();if(cutoff.isAfter(drawDate))throw new IllegalArgumentException("ELIGIBILITY_CUTOFF_DATE بعد از DRAW_DATE مجاز نیست.");String no=required(r.drawNo(),"DRAW_NO"),seed=required(r.randomSeedReference(),"RANDOM_SEED_REFERENCE"),audit=required(r.auditReference(),"AUDIT_REFERENCE");String h=hash("LOTTERY_DRAW|"+r.programId()+"|"+no+"|"+drawDate+"|"+cutoff+"|"+seed+"|"+audit);if(replayOrClaim(idem,accountId,"LOTTERY_DRAW_CREATE",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_LOTTERY_DRAW");repository.insertLotteryDraw(id,r.programId(),no,drawDate,cutoff,seed,audit,actor);repository.completeIdempotency(idem,"LOTTERY_DRAW:"+id);return view(accountId);}
    @Transactional public WaveDView createLotteryEntry(long accountId,LotteryEntryRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Lottery Entry الزامی است.");LotteryDrawLock draw=repository.lotteryDraw(r.lotteryDrawId());if(draw==null||!"OPEN".equals(draw.status()))throw new IllegalArgumentException("Lottery Draw باز یافت نشد.");if(!repository.enrollmentBelongsToAccount(r.rewardEnrollmentId(),accountId,draw.programId()))throw new IllegalArgumentException("Reward Enrollment فعال برای این Draw/Account یافت نشد.");BigDecimal balance=Objects.requireNonNull(r.eligibleBalance(),"ELIGIBLE_BALANCE الزامی است.");if(balance.signum()<0||r.entryCount()<1)throw new IllegalArgumentException("Eligible balance/entry count نامعتبر است.");String h=hash("LOTTERY_ENTRY|"+accountId+"|"+r.lotteryDrawId()+"|"+r.rewardEnrollmentId()+"|"+balance+"|"+r.entryCount());if(replayOrClaim(idem,accountId,"LOTTERY_ENTRY_CREATE",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_LOTTERY_ENTRY");repository.insertLotteryEntry(id,r.lotteryDrawId(),r.rewardEnrollmentId(),balance,r.entryCount(),actor);repository.completeIdempotency(idem,"LOTTERY_ENTRY:"+id);return view(accountId);}
    @Transactional public WaveDView registerLotteryWinner(long accountId,LotteryWinnerRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Lottery Winner الزامی است.");if(!repository.entryBelongsToAccount(r.lotteryEntryId(),accountId,r.lotteryDrawId()))throw new IllegalArgumentException("Lottery Entry متعلق به این حساب/Draw نیست.");BigDecimal amount=Objects.requireNonNull(r.prizeAmount(),"PRIZE_AMOUNT الزامی است.");if(amount.signum()<=0)throw new IllegalArgumentException("PRIZE_AMOUNT باید مثبت باشد.");String code=required(r.prizeCode(),"PRIZE_CODE");String h=hash("LOTTERY_WINNER|"+accountId+"|"+r.lotteryDrawId()+"|"+r.lotteryEntryId()+"|"+code+"|"+amount);if(replayOrClaim(idem,accountId,"LOTTERY_WINNER_REGISTER",h,actor,corr))return view(accountId);long id=repository.next("SEQ_DEPOSIT_LOTTERY_WINNER");repository.insertLotteryWinner(id,r.lotteryDrawId(),r.lotteryEntryId(),code,trim(r.prizeDescription()),amount,actor);repository.completeIdempotency(idem,"LOTTERY_WINNER:"+id);return view(accountId);}
    @Transactional public LotteryRunResult runLottery(long accountId,LotteryRunRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Lottery Run الزامی است.");if(!repository.activeProgramForAccount(r.programId(),accountId))throw new IllegalArgumentException("Reward Program فعال/مجاز برای این حساب نیست.");String prizeCode=upper(required(r.prizeCode(),"PRIZE_CODE"));if(!Set.of("CASH_PRIZE","NON_CASH_PRIZE").contains(prizeCode))throw new IllegalArgumentException("PRIZE_CODE نامعتبر است.");BigDecimal prizeAmount=Objects.requireNonNull(r.prizeAmount(),"PRIZE_AMOUNT الزامی است.");if(prizeAmount.signum()<=0)throw new IllegalArgumentException("PRIZE_AMOUNT باید مثبت باشد.");String key=required(idem,"X-Idempotency-Key"),h=hash("LOTTERY_RUN|"+r.programId()+"|"+prizeCode+"|"+prizeAmount);var prior=repository.idempotency(key);if(prior.isPresent()){IdemRow x=prior.get();if(!"LOTTERY_RUN".equals(x.operation())||!h.equals(x.payloadHash())||!Objects.equals(accountId,x.accountId())||!"COMPLETED".equals(x.status())||x.resultReference()==null||!x.resultReference().startsWith("LOTTERY_WINNER:"))throw new IllegalArgumentException("Idempotency-Key با Lottery Run قبلی سازگار نیست.");long winnerId=Long.parseLong(x.resultReference().substring("LOTTERY_WINNER:".length()));LotteryWinnerResult existing=repository.lotteryWinnerResult(winnerId);if(existing==null)throw new IllegalStateException("Lottery Winner قبلی یافت نشد.");long total=repository.lotteryDrawEntryCount(existing.lotteryDrawId());return new LotteryRunResult(existing.lotteryDrawId(),existing.lotteryWinnerId(),existing.winnerAccountId(),existing.winnerAccountNo(),total,existing.drawNo(),existing.auditReference(),view(accountId));}List<LotteryPoolRow> pool=repository.eligibleLotteryPool(r.programId());List<LotteryPoolRow> eligible=new ArrayList<>();long totalEntries=0;for(LotteryPoolRow row:pool){long count=row.eligibleBalance().divideToIntegralValue(row.entryUnitAmount()).longValue();if(count>0){eligible.add(row);totalEntries=Math.addExact(totalEntries,count);}}if(eligible.isEmpty()||totalEntries<=0)throw new IllegalArgumentException("عضو واجد شرایط با شانس مثبت برای قرعه‌کشی وجود ندارد.");repository.claimIdempotency(repository.next("SEQ_DEPOSIT_OPERATION_IDEMPOTENCY"),key,accountId,"LOTTERY_RUN",h,actor,corr);long drawId=repository.next("SEQ_DEPOSIT_LOTTERY_DRAW");String drawNo="DRAW-"+drawId,seed="SEED-"+UUID.randomUUID(),audit="AUD-"+UUID.randomUUID();LocalDate today=LocalDate.now();repository.insertLotteryDraw(drawId,r.programId(),drawNo,today,today,seed,audit,actor);long ticket=Math.floorMod(secureRandom.nextLong(),totalEntries),cursor=0,winnerEntryId=0,winnerAccountId=0;String winnerAccountNo=null;for(LotteryPoolRow row:eligible){long count=row.eligibleBalance().divideToIntegralValue(row.entryUnitAmount()).longValue();long entryId=repository.next("SEQ_DEPOSIT_LOTTERY_ENTRY");repository.insertLotteryEntry(entryId,drawId,row.rewardEnrollmentId(),row.eligibleBalance(),count,actor);if(winnerEntryId==0&&ticket<cursor+count){winnerEntryId=entryId;winnerAccountId=row.accountId();winnerAccountNo=row.accountNo();}cursor+=count;}if(winnerEntryId==0)throw new IllegalStateException("Lottery winner selection نامعتبر شد.");long winnerId=repository.next("SEQ_DEPOSIT_LOTTERY_WINNER");repository.insertLotteryWinner(winnerId,drawId,winnerEntryId,prizeCode,null,prizeAmount,actor);if(repository.verifyLotteryDraw(drawId,actor)!=1)throw new IllegalStateException("Lottery Draw قابل تأیید نیست.");repository.completeIdempotency(key,"LOTTERY_WINNER:"+winnerId);return new LotteryRunResult(drawId,winnerId,winnerAccountId,winnerAccountNo,totalEntries,drawNo,audit,view(accountId));}

    @Transactional public WaveDView payLotteryWinner(long accountId,long winnerId,PrizePaymentRequest r,String actor,String corr,String idem){requireAccount(accountId);if(r==null)throw new IllegalArgumentException("Prize Payment الزامی است.");WinnerLock w=repository.winnerForPayment(winnerId,accountId);if(w==null||!"VERIFIED".equals(w.status())||w.paymentTransactionId()!=null)throw new IllegalArgumentException("Winner قابل پرداخت یافت نشد.");String approver=required(r.approverUserId(),"APPROVER_USER_ID");if(actor.equalsIgnoreCase(approver))throw new IllegalArgumentException("Maker و Approver باید متفاوت باشند.");String paymentRef=trim(r.paymentReference())==null?"REWARD-WINNER-"+winnerId:trim(r.paymentReference());String currency=repository.accountCurrency(accountId);var tx=transactions.postDerived(new DerivedTransactionRequest(accountId,"REWARD_PRIZE_PAYMENT",w.prizeAmount(),currency,LocalDate.now(),LocalDate.now(),"CREDIT",paymentRef,"REWARD_PRIZE_PAYMENT",actor,approver,"WINNER_VERIFIED",List.of(new DerivedTransactionLeg(null,"REWARD_PRIZE_FUNDING","DEBIT",w.prizeAmount()),new DerivedTransactionLeg(accountId,null,"CREDIT",w.prizeAmount()))),actor,corr,idem+"-STEP05");long txId=tx.transaction().transaction().transactionId();if(repository.markWinnerPaid(winnerId,txId,"TX-"+txId,actor)!=1)throw new IllegalStateException("Winner همزمان تغییر کرده است.");return view(accountId);}

    private WaveDView view(long accountId){return new WaveDView(new ReconciliationView(repository.reconRuns(accountId),repository.reconItems(accountId),repository.discrepancies(accountId),repository.suspense(accountId)),new ExceptionView(repository.exceptionCases(accountId),repository.assignments(accountId),repository.corrections(accountId),repository.authorizations(accountId),repository.correctionEntries(accountId),repository.rootCauses(accountId)),new CorrespondentView(repository.correspondents(accountId)),new RewardView(repository.activePrograms(repository.currentProductVersion(accountId)),repository.enrollments(accountId),repository.lotteryDraws(accountId),repository.lotteryEntries(accountId),repository.lotteryWinners(accountId)));}
    private void requireAccount(long id){if(!repository.accountExists(id))throw new DepositAccountNotFoundException("حساب سپرده یافت نشد: "+id);}
    private boolean replayOrClaim(String key,long accountId,String operation,String payloadHash,String actor,String correlation){String k=required(key,"X-Idempotency-Key");var row=repository.idempotency(k);if(row.isPresent()){IdemRow x=row.get();if(!operation.equals(x.operation())||!payloadHash.equals(x.payloadHash())||!Objects.equals(accountId,x.accountId()))throw new IllegalArgumentException("Idempotency-Key با payload قبلی سازگار نیست.");if("COMPLETED".equals(x.status()))return true;throw new IllegalStateException("درخواست با Idempotency-Key در حال پردازش است.");}repository.claimIdempotency(repository.next("SEQ_DEPOSIT_OPERATION_IDEMPOTENCY"),k,accountId,operation,payloadHash,actor,correlation);return false;}
    private static String required(String v,String f){if(v==null||v.isBlank())throw new IllegalArgumentException(f+" الزامی است.");return v.trim();}
    private static String trim(String v){return v==null||v.isBlank()?null:v.trim();}
    private static String upper(String v){return v==null?null:v.trim().toUpperCase(Locale.ROOT);}
    private static String hash(String s){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
